import numpy as np

def normalize_image(image: np.ndarray, mean, std) -> np.ndarray:
    image = np.asarray(image)
    if image.ndim != 3:
        raise ValueError("image must be HxWxC")
    if image.dtype != np.uint8:
        raise ValueError("image must have dtype uint8")
    c = image.shape[2]
    mean = np.asarray(mean, dtype=np.float32)
    std = np.asarray(std, dtype=np.float32)
    if mean.shape != (c,) or std.shape != (c,):
        raise ValueError("mean and std must each have length C")
    if np.any(std <= 0):
        raise ValueError("std values must be positive")
    x = image.astype(np.float32) / np.float32(255.0)
    return ((x - mean[None, None, :]) / std[None, None, :]).astype(np.float32, copy=False)

import numpy as np

def binary_segmentation_metrics(pred, target, ignore_index=255) -> dict:
    pred = np.asarray(pred)
    target = np.asarray(target)
    if pred.shape != target.shape:
        raise ValueError("pred and target must have identical shapes")

    valid = target != ignore_index
    p = pred[valid] == 1
    t = target[valid] == 1

    tp = int(np.count_nonzero(p & t))
    fp = int(np.count_nonzero(p & ~t))
    fn = int(np.count_nonzero(~p & t))

    def ratio(num, den):
        return 1.0 if den == 0 else float(num / den)

    return {
        "tp": tp,
        "fp": fp,
        "fn": fn,
        "precision": ratio(tp, tp + fp),
        "recall": ratio(tp, tp + fn),
        "dice": ratio(2 * tp, 2 * tp + fp + fn),
        "iou": ratio(tp, tp + fp + fn),
    }

