import numpy as np

def clean_mask(mask: np.ndarray, kernel_size=3) -> np.ndarray:
    if not isinstance(kernel_size, (int, np.integer)) or kernel_size <= 0 or kernel_size % 2 == 0:
        raise ValueError("kernel_size must be a positive odd integer")
    binary = (np.asarray(mask) != 0).astype(np.uint8)
    kernel = cv2.getStructuringElement(
        cv2.MORPH_ELLIPSE, (int(kernel_size), int(kernel_size))
    )
    opened = cv2.morphologyEx(binary, cv2.MORPH_OPEN, kernel, iterations=1)
    closed = cv2.morphologyEx(opened, cv2.MORPH_CLOSE, kernel, iterations=1)
    return (closed != 0).astype(np.uint8)

import numpy as np

def backproject_depth(depth, fx, fy, cx, cy, depth_scale=1000.0, mask=None) -> np.ndarray:
    depth = np.asarray(depth, dtype=np.float64)
    if depth.ndim != 2:
        raise ValueError("depth must be 2D")
    if fx <= 0 or fy <= 0 or depth_scale <= 0:
        raise ValueError("fx, fy and depth_scale must be positive")

    valid = np.isfinite(depth) & (depth > 0)
    if mask is not None:
        mask = np.asarray(mask)
        if mask.shape != depth.shape:
            raise ValueError("mask shape must match depth")
        valid &= mask.astype(bool)

    v, u = np.indices(depth.shape)
    z = depth[valid] / float(depth_scale)
    x = (u[valid] - float(cx)) * z / float(fx)
    y = (v[valid] - float(cy)) * z / float(fy)
    return np.column_stack((x, y, z)).astype(np.float64, copy=False)

import numpy as np

def fit_plane_svd(points: np.ndarray) -> np.ndarray:
    pts = np.asarray(points, dtype=np.float64)
    if pts.ndim != 2 or pts.shape[1:] != (3,) or len(pts) < 3:
        raise ValueError("points must have shape (N,3), N>=3")
    if not np.all(np.isfinite(pts)):
        raise ValueError("all points must be finite")

    centroid = pts.mean(axis=0)
    centered = pts - centroid
    if np.linalg.matrix_rank(centered) < 2:
        raise ValueError("centered points must have rank at least 2")

    _, _, vh = np.linalg.svd(centered, full_matrices=False)
    normal = vh[-1].astype(np.float64)
    norm = np.linalg.norm(normal)
    if norm == 0:
        raise ValueError("invalid plane normal")
    normal /= norm

    for component in normal:
        if abs(component) > 1e-12:
            if component < 0:
                normal = -normal
            break

    d = -float(np.dot(normal, centroid))
    return np.array([normal[0], normal[1], normal[2], d], dtype=np.float64)

import numpy as np

def bbox_from_mask(mask: np.ndarray):
    mask = np.asarray(mask)
    if mask.ndim != 2:
        raise ValueError("mask must be 2D")
    ys, xs = np.nonzero(mask)
    if xs.size == 0:
        return None
    return (
        int(xs.min()),
        int(ys.min()),
        int(xs.max()) + 1,
        int(ys.max()) + 1,
    )

import torch
from torch import nn

class ConvBNReLU(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3):
        super().__init__()
        if not isinstance(kernel_size, int) or kernel_size <= 0 or kernel_size % 2 == 0:
            raise ValueError("kernel_size must be a positive odd integer")
        self.block = nn.Sequential(
            nn.Conv2d(
                in_channels,
                out_channels,
                kernel_size=kernel_size,
                stride=1,
                padding=kernel_size // 2,
                bias=False,
            ),
            nn.BatchNorm2d(out_channels),
            nn.ReLU(inplace=True),
        )

    def forward(self, x):
        return self.block(x)

import torch
import torch.nn.functional as F

def binary_focal_loss_with_logits(
    logits, targets, alpha=0.25, gamma=2.0, reduction="mean"
):
    if logits.shape != targets.shape:
        raise ValueError("logits and targets must have the same shape")
    if reduction not in ("none", "mean", "sum"):
        raise ValueError("invalid reduction")

    targets = targets.to(device=logits.device, dtype=logits.dtype)
    bce = F.binary_cross_entropy_with_logits(logits, targets, reduction="none")
    p = torch.sigmoid(logits)
    pt = torch.where(targets == 1, p, 1 - p)

    alpha_pos = torch.as_tensor(alpha, dtype=logits.dtype, device=logits.device)
    alpha_t = torch.where(targets == 1, alpha_pos, 1 - alpha_pos)
    loss = alpha_t * (1 - pt).pow(gamma) * bce

    if reduction == "mean":
        return loss.mean()
    if reduction == "sum":
        return loss.sum()
    return loss

