import torch

def scaled_dot_product_attention(q, k, v, mask=None):
    if q.ndim != 4 or k.ndim != 4 or v.ndim != 4:
        raise ValueError("q, k, v must be [B,H,N,D]")
    if q.shape[:2] != k.shape[:2] or k.shape[:2] != v.shape[:2]:
        raise ValueError("batch/head dimensions must match")
    if q.shape[-1] != k.shape[-1] or k.shape[-2] != v.shape[-2]:
        raise ValueError("incompatible q/k/v dimensions")

    scores = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(q.shape[-1])
    if mask is not None:
        mask = torch.as_tensor(mask, dtype=torch.bool, device=scores.device)
        scores = scores.masked_fill(~mask, float("-inf"))

    attention_weights = torch.softmax(scores, dim=-1)
    output = torch.matmul(attention_weights, v)
    return output, attention_weights

import numpy as np

def confusion_matrix(y_true, y_pred, num_classes: int, ignore_index=None) -> np.ndarray:
    if num_classes <= 0:
        raise ValueError("num_classes must be positive")

    yt = np.asarray(y_true).reshape(-1)
    yp = np.asarray(y_pred).reshape(-1)
    if yt.shape != yp.shape:
        raise ValueError("y_true and y_pred must contain the same number of elements")

    if ignore_index is not None:
        keep = yt != ignore_index
        yt = yt[keep]
        yp = yp[keep]

    if np.any((yt < 0) | (yt >= num_classes)) or np.any((yp < 0) | (yp >= num_classes)):
        raise ValueError("class id out of range")

    encoded = yt.astype(np.int64) * int(num_classes) + yp.astype(np.int64)
    counts = np.bincount(encoded, minlength=num_classes * num_classes)
    return counts.reshape(num_classes, num_classes).astype(np.int64, copy=False)

import torch

@torch.no_grad()
def update_ema(ema_model, model, decay: float) -> None:
    if not 0.0 <= decay <= 1.0:
        raise ValueError("decay must be in [0,1]")

    src_params = dict(model.named_parameters())
    ema_params = dict(ema_model.named_parameters())
    if src_params.keys() != ema_params.keys():
        raise ValueError("parameter names do not match")

    for name, ema_param in ema_params.items():
        ema_param.mul_(decay).add_(src_params[name].detach(), alpha=1.0 - decay)

    src_buffers = dict(model.named_buffers())
    ema_buffers = dict(ema_model.named_buffers())
    if src_buffers.keys() != ema_buffers.keys():
        raise ValueError("buffer names do not match")

    for name, ema_buffer in ema_buffers.items():
        ema_buffer.copy_(src_buffers[name].detach())

import math

class EarlyStopping:
    def __init__(self, patience=5, min_delta=0.0):
        if patience < 1:
            raise ValueError("patience must be >= 1")
        if min_delta < 0:
            raise ValueError("min_delta must be >= 0")
        self.patience = int(patience)
        self.min_delta = float(min_delta)
        self.best = None
        self.bad_epochs = 0

    def step(self, metric) -> bool:
        value = float(metric)
        improved = (
            math.isfinite(value)
            and (self.best is None or value < self.best - self.min_delta)
        )

        if improved:
            self.best = value
            self.bad_epochs = 0
            return False

        self.bad_epochs += 1
        return self.bad_epochs >= self.patience

def freeze_for_finetuning(model, trainable_prefixes) -> int:
    prefixes = tuple(trainable_prefixes)
    trainable_count = 0

    for name, parameter in model.named_parameters():
        trainable = any(name.startswith(prefix) for prefix in prefixes)
        parameter.requires_grad_(trainable)
        if trainable:
            trainable_count += parameter.numel()

    return int(trainable_count)

import numpy as np

def weighted_box_fusion(boxes, scores, iou_threshold=0.55):
    boxes = np.asarray(boxes, dtype=np.float64)
    scores = np.asarray(scores, dtype=np.float64)
    if boxes.ndim != 2 or boxes.shape[1:] != (4,) or scores.shape != (len(boxes),):
        raise ValueError("invalid boxes/scores shapes")
    if np.any(scores < 0):
        raise ValueError("scores must be non-negative")

    def iou(a, b):
        lt = np.maximum(a[:2], b[:2])
        rb = np.minimum(a[2:], b[2:])
        wh = np.maximum(rb - lt, 0.0)
        inter = wh[0] * wh[1]
        awh = np.maximum(a[2:] - a[:2], 0.0)
        bwh = np.maximum(b[2:] - b[:2], 0.0)
        union = awh[0] * awh[1] + bwh[0] * bwh[1] - inter
        return 0.0 if union <= 0 else float(inter / union)

    order = np.lexsort((np.arange(len(scores)), -scores))
    clusters = []

    for idx in order:
        idx = int(idx)
        joined = False
        for cluster in clusters:
            if iou(boxes[idx], cluster["fused_box"]) >= iou_threshold:
                cluster["indices"].append(idx)
                inds = np.asarray(cluster["indices"], dtype=int)
                weights = scores[inds]
                weight_sum = weights.sum()
                if weight_sum > 0:
                    cluster["fused_box"] = np.average(
                        boxes[inds], axis=0, weights=weights
                    )
                else:
                    cluster["fused_box"] = boxes[inds].mean(axis=0)
                joined = True
                break

        if not joined:
            clusters.append({
                "indices": [idx],
                "fused_box": boxes[idx].copy(),
            })

    if not clusters:
        return np.empty((0, 4), dtype=np.float64), np.empty((0,), dtype=np.float64)

    fused_boxes = np.stack([c["fused_box"] for c in clusters]).astype(np.float64)
    fused_scores = np.array(
        [scores[np.asarray(c["indices"], dtype=int)].mean() for c in clusters],
        dtype=np.float64,
    )
    return fused_boxes, fused_scores

import numpy as np

def update_centroid_tracks(prev_tracks, detections, max_distance: float) -> dict:
    if max_distance < 0:
        raise ValueError("max_distance must be non-negative")

    detections = np.asarray(detections, dtype=np.float64)
    if detections.size == 0:
        detections = detections.reshape(0, 2)
    if detections.ndim != 2 or detections.shape[1:] != (2,):
        raise ValueError("detections must have shape (N,2)")

    normalized_tracks = {}
    for track_id, centroid in prev_tracks.items():
        c = np.asarray(centroid, dtype=np.float64)
        if c.shape != (2,):
            raise ValueError("each previous centroid must have shape (2,)")
        normalized_tracks[int(track_id)] = c

    candidates = []
    for track_id, centroid in normalized_tracks.items():
        if len(detections):
            distances = np.linalg.norm(detections - centroid, axis=1)
            for det_index in np.flatnonzero(distances <= max_distance):
                candidates.append(
                    (float(distances[det_index]), int(track_id), int(det_index))
                )

    candidates.sort(key=lambda item: (item[0], item[1], item[2]))

    used_tracks = set()
    used_detections = set()
    result = {}

    for _, track_id, det_index in candidates:
        if track_id in used_tracks or det_index in used_detections:
            continue
        result[track_id] = detections[det_index].astype(np.float64, copy=True)
        used_tracks.add(track_id)
        used_detections.add(det_index)

    next_id = max(normalized_tracks.keys(), default=-1) + 1
    for det_index in range(len(detections)):
        if det_index not in used_detections:
            result[next_id] = detections[det_index].astype(np.float64, copy=True)
            next_id += 1

    return result
